/* Draws the moby's beam: orients the moby along its child's two joints, draws three quads and a ribbon of 196 points.
   */
void draw_joint_aligned_beam_effect(Moby *m) {
    Quad pk;
    Vec4A mtx[4];
    Vec4A out[2];
    Ids ids;
    Vec4A up;
    Vec4A res[4];
    Vec4A idm[4];
    Vec4A a;
    Vec4A b;
    Vec4A c;
    Vec4A d;
    Vec4A e;
    Data_2B4918 *data = (Data_2B4918 *)m->pvars;
    Child *child = data->child;
    int i;

    if (child == 0 || child->cls != 0x260) {
        return;
    }
    pk.tag[2] = 0xFF9000000260;
    pk.tag[3] = 0x8000000048;
    pk.tag[0] = 0;
    if (data->f4 != 0) {
        ids = joint_beam_alt_joint_ids;
        transform_scaled_vertex_batch(child, 2, &ids, out);
    } else {
        ids = joint_beam_joint_ids;
        transform_scaled_vertex_batch(child, 2, &ids, out);
    }
    *(Q_2B4918 *)&up = 0;
    up.y = 1.0f;
    FastVecSub(&mtx[2], &out[0], &out[1]);
    vec_scale_to_length(&mtx[2], &mtx[2], 1.0f);
    mtx[2].w = 0.0f;
    FastVecCross(&mtx[0], &up, &mtx[2]);
    vec_scale_to_length(&mtx[0], &mtx[0], 1.0f);
    mtx[0].w = 0.0f;
    FastVecCross(&mtx[1], &mtx[2], &mtx[0]);
    mtx[1].w = 0.0f;
    qcopy(&mtx[3], &out[1]);
    mtx[3].w = 1.0f;
    qcopy(&m->rot_row0, &mtx[0]);
    qcopy(&m->rot_row1, &mtx[1]);
    qcopy(&m->rot_row2, &mtx[2]);
    qcopy(&m->pos, &mtx[3]);
    set_identity_matrix(idm);
    idm[3].w = 1.0f;
    idm[3].z = -0.075f;
    idm[3].x = 0.0f;
    idm[3].y = 0.0f;
    multiply_matrix(res, mtx, idm);
    pk.tag[1] = GetEffectTex_r(0xC);
    for (i = 0; i < 4; i++) {
        pk.col[i] = 0x80808080;
        if (i == 0 || i == 2) {
            FastVecScale(pk.pos[i], joint_beam_quad_a_corners[i], data->f2C);
        } else {
            float *v = pk.pos[i];
            FastVecScale(v, joint_beam_quad_a_corners[i], data->f2C);
            v[2] -= random_float_between(0.0f, 0.1f);
        }
        pk.uv[i][0] = joint_beam_quad_uvs[i][0];
        pk.uv[i][1] = joint_beam_quad_uvs[i][1];
    }
    draw_world_quad(&pk, res, 0);
    for (i = 0; i < 4; i++) {
        if (i == 0 || i == 2) {
            FastVecScale(pk.pos[i], joint_beam_quad_b_corners[i], data->f2C);
        } else {
            float *v = pk.pos[i];
            FastVecScale(v, joint_beam_quad_b_corners[i], data->f2C);
            v[2] -= random_float_between(0.0f, 0.1f);
        }
    }
    draw_world_quad(&pk, res, 0);
    pk.tag[1] = GetEffectTex_r(0xB);
    FastVecScale(&d, &mtx[2], -0.13f);
    FastVecAdd(&d, &d, &mtx[3]);
    FastVecSub(&a, g_debug_camera_r2, &d);
    vec_scale_to_length(&a, &a, 1.0f);
    FastVecCross(&b, &a, &g_hero.gravity_dir);
    vec_scale_to_length(&b, &b, -1.0f);
    FastVecCross(&c, &b, &a);
    pk.col[0] = pk.col[1] = pk.col[2] = pk.col[3] = 0x7F2020FF;
    for (i = 0; i < 4; i++) {
        FastVecScale(pk.pos[i], joint_beam_quad_a_corners[i], 0.1f);
        transform_vector(pk.pos[i], pk.pos[i], &a);
    }
    draw_world_quad(&pk, 0, 0);
    VU1_addGSregister(6, GetEffectTex_r(0xA));
    VU1_addGSregister(0x42, pk.tag[3]);
    VU1_addGSregister(8, 0);
    VU1_addGSregister(0x14, 0xFF9000000260);
    VU1_addGSregister(0x4A, 0);
    font_queue_vu_state();
    for (i = 0; i < 0xC4; i++) {
        FastVecScale(&e, joint_beam_ribbon_model_points[i], data->f20);
        transform_vector(&e, &e, mtx);
        l00_beam_ribbon_world_positions[i].x = e.x;
        l00_beam_ribbon_world_positions[i].y = e.y;
        l00_beam_ribbon_world_positions[i].z = e.z;
        joint_beam_ribbon_uvs[i].v -= 0.025f;
        if (joint_beam_ribbon_uvs[i].v < -7.0f) {
            joint_beam_ribbon_uvs[i].v += 7.0f;
        }
    }
    draw_env_overlay_mesh(0x94, l00_beam_ribbon_world_positions, joint_beam_ribbon_colors, joint_beam_ribbon_uvs, 1);
    draw_env_overlay_mesh(0x32, &l00_beam_ribbon_world_positions[0x92], &joint_beam_ribbon_colors[0x92],
                          &joint_beam_ribbon_uvs[0x92], 1);
}
