/* Adapted from Lombyte's project (GPL-3.0) for PAL by OpenRAC's tools/port.py: src/overlays/shared/unclassified_002b2100.c, FUN_L00_002b3c50. */
void emit_beam_trail_particles(X *x) {
    V4 l0;
    V4 a;
    V4 d;
    V4 t;
    N *g;
    f32 s;
    f32 q;
    u32 col;
    s32 i;
    s32 n;
    s32 m;
    u8 *p;

    g = x->f78;
    l0.f[0] = FastCos(random_angle_radians()) * 0.05f;
    l0.f[1] = FastSin(random_angle_radians()) * 0.05f;
    l0.f[2] = 0.0f;
    l0.f[2] = -random_float_between(0.01f, 0.03f);
    transform_vector_by_basis(&l0, &l0, &x->vC0);
    qcopy(&a, &x->v10);
    if (g_hero.state.current == HERO_STATE_DELAYED_JUMP_OR_R1_REPEAT_EXIT_WAIT) {
        if ((*(s32 *)&D_L00_0015F6B0_B4F40b) % 3 == 0) {
            spawn_burst(&a, &l0, 0x4F007FFF, 0x1FFFFFFF, scale_ticks(10), 1, 10000.0f);
        }
    } else {
        spawn_burst(&a, &l0, 0x4F007FFF, 0x1FFFFFFF, scale_ticks(10), 1, 10000.0f);
    }
    if (g->f0C) {
        s = FastVecDist_r2(&g->v10, &a) * 0.5f;
        FastVecSub_r2(&d, &g->v10, &a);
        for (i = 1; i < 2; i++) {
            vec_scale_to_length_r2(&t, &d, s * (f32)i);
            FastVecAdd_r3(&t, &a, &t);
            spawn_burst(&t, &l0, 0x4F007FFF, 0x1FFFFFFF, scale_ticks(10), 1, 10000.0f);
        }
    }
    g->f00 = random_integer_below(scale_ticks(10));
    q = 1.075f;
    col = 0x808080;
    l0.f[0] = 0.0f;
    l0.f[1] = 0.0f;
    l0.f[2] = -0.3f;
    l0.f[3] = 1.0f;
    transform_vector_by_basis(&l0, &l0, &x->vC0);
    FastVecAdd_r3(&a, &x->v10, &l0);
    l0.f[3] = 1.0f;
    l0.f[2] = -0.075f;
    l0.f[0] = 0.0f;
    l0.f[1] = 0.0f;
    transform_vector_by_basis(&l0, &l0, &x->vC0);
    l0.f[2] = 0.025f;
    if (g_hero.state.current == HERO_STATE_LAND) {
        col = 0xA0A0A0;
        q = 1.0165f;
        l0.f[2] -= g_frame_time * 5.0f;
    }
    if (g_hero.state.current == HERO_STATE_DELAYED_JUMP_OR_R1_REPEAT_EXIT_WAIT) {
        col = 0xA0A0A0;
        q = 1.037f;
        l0.f[2] -= g_frame_time * 3.0f;
    }
    p = PartType23Spawn_v(&a, 0.05f, 1.01f, q, 30000.0f, 6, &l0, col);
    if (p)
        p[3] = 0x44;
    if (g->f0C) {
        s = FastVecDist_r2(&g->v10, &a) * 0.16667f;
        FastVecSub_r2(&d, &g->v10, &a);
        m = g_hero.state.current;
        n = 4;
        if (m == 8)
            n = 2;
        if (m == 0x81)
            n = 1;
        for (i = 1; i < n; i++) {
            vec_scale_to_length_r2(&t, &d, s * (f32)i);
            FastVecAdd_r3(&t, &a, &t);
            p = PartType23Spawn_v(&t, 0.05f, 1.01f, q, 30000.0f, 6, &l0, col);
            if (p)
                p[3] = 0x44;
        }
    }
    qcopy(&g->v10, &a);
    g->f0C = 1;
}

