/* Multi-state update for a timed object: random delays from scale_ticks pace the stages, which adjust the step and scale fields of its private block and call the shared callback. Adapted from Lombyte's project (GPL-3.0) for PAL: overlays/shared/unclassified_002b2100.c, FUN_L00_002b4198. */
void thruster_pack_flame_update(void *p) {
    O_4198 *o = (O_4198 *)p;
    V_4198 *v = o->v;
    s32 flag = 0;
    s32 st;
    s32 lim;

    if ((&g_hero_r)->items[3].item_id == 3) {
        if (o->state == 1 || o->state == 3) {
            st = (&g_hero_r)->state.current;
            if ((u32)(st - 0xB) < 4 ||
                (st == 0x1C && ((u8 *)((void *)(&g_hero_r)->moby))[0x52] == ((u8 *)((void *)(&g_hero_r)->moby))[0x53] &&
                 (&g_hero_r)->anim_frame >= 6.0f && (&g_hero_r)->anim_frame <= 16.0f)) {
                if (!(&g_hero_r)->past_jump_apex)
                    flag = 1;
            }
            if ((&g_hero_r)->state.current == HERO_STATE_PACK_LONG_JUMP) {
                if ((&g_hero_r)->state_timer < scale_ticks(0x2C)) {
                    flag = 1;
                }
            }
            if ((&g_hero_r)->state.current == HERO_STATE_RISE_THEN_FALL_WITH_AIRBORNE_HIT_QUERY) {
                if ((&g_hero_r)->state_timer < scale_ticks(0xF) ||
                    (scale_ticks(0x21) < (&g_hero_r)->state_timer && (&g_hero_r)->air_frames.s != 0)) {
                    flag = 1;
                }
            }
            if ((&g_hero_r)->state.current == HERO_STATE_LAND ||
                (&g_hero_r)->state.current == HERO_STATE_DELAYED_JUMP_OR_R1_REPEAT_EXIT_WAIT) {
                flag = 1;
            }
        }
    }
    switch (o->state) {
        case 0:
            o->f18 += 0.5f;
            o->state = 1;
            o->u30 = 0xFF;
            o->u34 |= 1;
            break;
        case 1:
            if (hero_slot_item_id(3) != 3) {
                DeleteMoby(o);
            } else if (flag != 0) {
                o->state = 2;
                v->i0 = scale_ticks(2);
                v->f30 = 0.0125f / scale_ticks(2);
                v->f34 = 0.2f / scale_ticks(2);
                v->f38 = 0.05f / scale_ticks(2);
                v->f3C = 0.025f / scale_ticks(2);
                v->f20 = 0.0f;
                v->f24 = 0.0f;
                v->f28 = 0.0f;
                v->f2C = 0.0f;
            }
            break;
        case 2:
            v->f20 += v->f30;
            v->f24 += v->f34;
            v->f28 += v->f38;
            v->f2C += v->f3C;
            v->i8 = (s32)(&g_hero_r)->items[3].moby;
            AddDrawCallback_r(draw_joint_aligned_beam_effect_r, o);
            if (fast_dec_timer(v) != 0) {
                o->state = 3;
                v->f20 = 0.0125f;
                v->f24 = 0.2f;
                v->f28 = 0.05f;
                v->iC = 0;
                v->f2C = 0.025f;
            }
            break;
        case 3:
            v->i8 = (s32)(&g_hero_r)->items[3].moby;
            AddDrawCallback_r(draw_joint_aligned_beam_effect_r, o);
            if (flag == 0) {
                o->state = 4;
                v->i0 = scale_ticks(8);
                v->f30 = 0.0125f / scale_ticks(8);
                v->f34 = 0.2f / scale_ticks(8);
                v->f38 = 0.05f / scale_ticks(8);
                v->f3C = 0.025f / scale_ticks(8);
            } else {
                v->f20 = 0.0125f;
                emit_beam_trail_particles_r(o);
            }
            break;
        case 4:
            if (fast_dec_timer(v) != 0) {
                o->state = 1;
            } else {
                v->f20 -= v->f30;
                v->f24 -= v->f34;
                v->f28 -= v->f38;
                v->f2C -= v->f3C;
                v->i8 = (s32)(&g_hero_r)->items[3].moby;
                AddDrawCallback_r(draw_joint_aligned_beam_effect_r, o);
            }
            break;
    }
}
