// Finds the best-aimed target moby in the global list for a given yaw and pitch, refining them. Adapted from Lombyte's project (GPL-3.0) for PAL: overlays/shared/unclassified_002b2100.c, FUN_L00_002b46a8.
unsigned char *select_blaster_auto_aim_target(int ign, Vec4 *from, float *yaw, float *pitch) {
    Vec4 src;
    Vec4 tp;
    Vec4 w;
    Moby *m;
    unsigned char *r;
    unsigned char *best;
    float bestd;
    float a;
    float b;
    float dy;
    float d;
    float e;
    float s;
    float t;
    struct Hero *g;

    best = 0;
    src.q = from->q;
    from = &src;
    bestd = 20.0f;
    for (m = (Moby *)suck_moby_list; m != 0; m = m->next) {
        if ((signed char)m->state < 0) {
            continue;
        }
        qcopy(&tp, &m->pos);
        r = GetFlaggedPvarWord(m);
        if (r != 0) {
            tp.f[2] += *(float *)(r + 0x10);
        } else {
            tp.f[2] += 0.5f;
        }
        if (!(m->flags & 0x1000)) {
            continue;
        }
        a = fast_atan2(tp.f[0] - from->f[0], tp.f[1] - from->f[1]);
        b = fast_atan2(vec_distance_xy(from, &tp), tp.f[2] - from->f[2]);
        dy = FastDiffRots(*yaw, a);
        d = fast_vec_dist(from, &tp);
        if (bestd < d) {
            continue;
        }
        g = &g_hero;
        BuildSphericalOffset(&w, d, *yaw, *pitch + g->ground_pitch.f * 0.5f);
        FastVecAdd(&w, &w, from);
        e = FastArcSin(fast_vec_dist(&w, &tp) / (d + d));
        e = e + e;
        if (0.15707964f < e) {
            r = GetFlaggedPvarWord(m);
            if (r != 0) {
                s = IntToFloat(r[0xA]) * 0.125f;
                t = FastArcSin(s / d);
                if (s < d) {
                    e -= t;
                    if (e < 0.0f) {
                        e = 0.0f;
                    }
                }
            }
        }
        if (e < 0.15707964f) {
            if (coll_line(g_debug_camera, &tp, 6, ign, 0) || coll_line(from, &tp, 6, ign, 0)) {
                return best;
            }
            *pitch = -b;
            bestd = d;
            if (dy < 0.17453292f) {
                *yaw = a;
            }
            best = (unsigned char *)m;
        }
    }
    return best;
}
