/* Blaster update: aims (reticle in first person, auto-aim otherwise), fires a shot with its sparks,
   keeps the usage statistics, returns to idle and moves the muzzle light. */
extern void blaster_update(Moby *m);
void blaster_update(Moby *m) {
    V_2B5C98 velocity;
    V_2B5C98 tpoint;
    V_2B5C98 launch;
    Work w;
    M4_2B5C98 inverse;
    V_2B5C98 reach;
    V_2B5C98 end;
    Moby *target;
    float yaw;
    float pitch;
    float yaw0, pitch0;
    float a, b, c;
    Data_2B5C98 *data;
    Stats_2B5C98 *stats;
    int i;

    velocity.q = 0;
    target = 0;
    pitch = 0.0f;
    data = (Data_2B5C98 *)m->pvars;
    if (m->state == 0) {
        m->state = 1;
        data->light = -1;
        data->glow = 0;
    }
    FastDecTimer_r2(&data->lock);
    fast_dec_timer_r3(&data->cooldown);
    if (hero_2B33E8.state.current == HERO_STATE_LOOK)
        HeroEnterMoveState_r2(HERO_STATE_LOOK_RELEASE_WAIT, 1);
    if (m->prev_seq == 0 && m->prev_frame < 3)
        data->cooldown = scale_ticks(7);
    if (hero_2B33E8.state.current == HERO_STATE_LOOK_RELEASE_WAIT && (hero_2B33E8.moby->flags & 1)) {
        copy_matrix3x4(&w.rotation, player_camera_r);
        matrix_from_basis_rows(&inverse, &w.rotation);
        velocity.f.z = g_frame_time_r * 40.0f;
        transform_vector(&velocity, &velocity, &inverse);
        clear_u64_value(&launch);
        launch.f.x += 0.15f;
        launch.f.z += 0.75f;
        launch.f.y += 0.15f;
        transform_vector(&launch, &launch, &inverse);
        FastVecAdd(&launch, &launch, player_camera_r + 0x140);
        if (hero_2B33E8.state.current == HERO_STATE_LOOK_RELEASE_WAIT && (hero_2B33E8.moby->flags & 1) &&
            !hero_2B33E8.item_use_locked) {
            EffectQueue_Add_r2((int)m, 0xFF0F0FFF, 1.0f, 0, 0.0f, 0x26, -1, 90.0f, 4);
            vec_scale_to_length(&reach, &velocity, 20.0f);
            FastVecAdd(&end, &reach, &launch);
            reach = end;
            if (coll_line(player_camera_r + 0x140, &reach, 0, (int)m, 0)) {
                if (g_coll_hit_moby_r && (g_coll_hit_moby_r->flags & 0x1000))
                    target = g_coll_hit_moby_r;
            }
        }
    } else {
        velocity.f.x = g_frame_time_r * 40.0f;
        transform_vector_by_basis(&velocity, &velocity, &hero_2B33E8.basis);
        moby_point_position(m, 0, &launch);
    }
    if (hero_2B33E8.items[6].locked_on)
        yaw = hero_2B33E8.items[6].lock_yaw;
    else
        yaw = fast_atan2(velocity.f.x, velocity.f.y);
    pitch = -fast_atan2(vector_length_xy(&velocity), velocity.f.z);
    yaw0 = yaw;
    pitch0 = pitch;
    if (hero_2B33E8.state.current != HERO_STATE_LOOK_RELEASE_WAIT) {
        if (hero_2B33E8.unk22C8 == 1) {
            yaw = m->rot.z;
            yaw0 = yaw;
            pitch = weapon_aim_mode1_launch_pitch;
            pitch0 = pitch;
        }
        target = select_blaster_auto_aim_target_r(m, &launch, &yaw, &pitch);
    }
    if (target && data->lock == 0) {
        if (get_ammo(-1)) {
            Aim_2B5C98 *r = GetFlaggedPvarWord_r2(target);
            float d = fast_vec_dist(g_debug_camera_r, &target->pos) / 50.0f;
            float h;
            qcopy(&w.point, &target->pos);
            h = 0.5f;
            if (r)
                h = r->height;
            w.point.f.z += h;
            EffectQueue_Add_r2((int)m, 0xFF0FFF0F, absolute_float(0.9f - d * 0.65f), &w.point, 0.0f, 0x26, -1, 90.0f,
                               4);
        }
    }
    if (hero_2B33E8.item_anim_active && hero_2B33E8.state.current != 0x72 && cinematic_mode != 2) {
        if (scale_ticks(5 - order_2B5C98.level) < hero_2B33E8.item_anim_frames && data->cooldown == 0) {
            if (use_ammo(-1, 1) && !hero_2B33E8.item_use_locked) {
                data->cooldown = scale_ticks(6);
                if (target) {
                    float speed = g_frame_time_r * 40.0f;
                    Aim_2B5C98 *r;
                    qcopy(&tpoint, &target->pos);
                    r = GetFlaggedPvarWord_r2(target);
                    if (r)
                        tpoint.f.z += r->height;
                    else
                        tpoint.f.z += 0.5f;
                    pitch = -fast_atan2(vec_distance_xy(&launch, &tpoint), tpoint.f.z - launch.f.z);
                    pitch0 -= hero_2B33E8.ground_pitch.f * 0.5f;
                    if (FastDiffRots(pitch0, pitch) < 0.17453292f) {
                        pitch0 = pitch;
                    } else if (FastAddRots(pitch0, 0.17453292f) < pitch) {
                        pitch0 = FastAddRots(pitch0, 0.17453292f);
                    } else if (pitch < FastAddRots(pitch0, -0.17453292f)) {
                        pitch0 = FastAddRots(pitch0, -0.17453292f);
                    }
                    BuildSphericalOffset(&w.point, speed, yaw0, -pitch0);
                    FastVecAdd(&w.point, &w.point, &launch);
                    yaw = fast_atan2(tpoint.f.x - w.point.f.x, tpoint.f.y - w.point.f.y);
                    pitch = -fast_atan2(vec_distance_xy(&w.point, &tpoint), tpoint.f.z - w.point.f.z);
                } else if (hero_2B33E8.state.current != HERO_STATE_LOOK_RELEASE_WAIT) {
                    pitch -= hero_2B33E8.ground_pitch.f * 0.5f;
                    pitch0 -= hero_2B33E8.ground_pitch.f * 0.5f;
                }
                w.spawn.flags = 0x10000;
                w.spawn.owner = m;
                w.spawn.f1C = 0.25f;
                w.spawn.i20 = 1;
                w.spawn.pos.f.x = FastCos(fast_atan2(hero_2B33E8.facing_x, hero_2B33E8.facing_y));
                w.spawn.pos.f.y = FastSin(fast_atan2(hero_2B33E8.facing_x, hero_2B33E8.facing_y));
                w.spawn.pos.f.z = 1.0f;
                w.spawn.pos.f.w = 5627.9248f;
                w.spawn.b18 = 1;
                w.spawn.b19 = 1;
                w.spawn.cls = (*(unsigned short *)&m->oclass);
                transform_hero_local_offset_to_world(&inverse, 0.7f, -0.15f, 0.5f);
                coll_sphere_mobys_r(&inverse, 0.42f, 5, hero_2B33E8.moby, &w.spawn);
                spawn_homing_shot(hero_2B33E8.moby, yaw, pitch, yaw0, pitch0, &launch, target);
                data->glow = scale_ticks(15);
                for (i = 0; i < 5; i++) {
                    w.spray.rnd.q = 0;
                    w.spray.rnd.f.x = random_float_between(-1.0f, 1.0f);
                    w.spray.rnd.f.y = random_float_between(-1.0f, 1.0f);
                    w.spray.rnd.f.z = random_float_between(-1.0f, 1.0f);
                    w.spray.v = w.spray.rnd;
                    vec_scale_to_length(&w.spray.v, &w.spray.v, FastVecLength(&velocity) * 0.65f);
                    FastVecAdd(&w.spray.v, &velocity, &w.spray.v);
                    vec_scale_to_length(&w.spray.v, &w.spray.v,
                                        random_float_between(g_frame_time_r * 3.0f, g_frame_time_r * 6.0f));
                    PartType27Spawn(&launch, &w.spray.v, 0x5F2F4F6F,
                                    random_int_between(scale_ticks(5), scale_ticks(10)), 10000.0f);
                }
                vec_scale_to_length(&velocity, &velocity, g_frame_time_r * 0.5f);
                PartType27Spawn(&launch, &velocity, 0x2F4F7F7F, random_int_between(scale_ticks(4), scale_ticks(7)),
                                200000.0f);
            }
            if (m->prev_seq != 4)
                MobyBlendAnimation(m, 4, 0, scale_ticks(7));
            stats = (Stats_2B5C98 *)(help_stats_base_r + 0x65);
            if (stats->uses < 65535)
                stats->uses++;
            if (scale_ticks(gameplay_event_frame_count_r) / 600 > stats->longest)
                stats->longest = scale_ticks(gameplay_event_frame_count_r) / 600;
            stats->levels = (stats->levels | (1 << g_current_level_index_r)) | 0x80000000;
        }
    }
    if (!(((((Input *)g_controller_state_r)->held & hero_2B33E8.items[0].button_mask) && get_ammo(-1)) ||
          (!(scale_ticks(9) < hero_2B33E8.item_anim_frames) && hero_2B33E8.item_anim_active)) ||
        hero_2B33E8.state.current == 0x72 || cinematic_mode == 2) {
        if ((m->prev_seq != 0 || (m->anim_flags & 2)) && hero_2B33E8.state.current != 0x72 && cinematic_mode != 2) {
            if (m->prev_seq != 1)
                MobyBlendAnimation(m, 1, 0, scale_ticks(7));
        } else if (hero_2B33E8.state.current == 0x72 || cinematic_mode == 2) {
            MobySetAnimation(m, 1, 0);
            MobyAnimAdvance(m);
        }
        cancel_hero_item_animation();
        data->cooldown = 0;
    }
    if (m->seq != 2 && data->glow > 0) {
        a = IntToFloat(data->glow < scale_ticks(9) ? data->glow : scale_ticks(9)) * 0.7f / (float)scale_ticks(9);
        b = IntToFloat(data->glow < scale_ticks(9) ? data->glow : scale_ticks(9)) * 0.7f / (float)scale_ticks(9);
        c = IntToFloat(data->glow < scale_ticks(9) ? data->glow : scale_ticks(9)) * 0.7f / (float)scale_ticks(9);
        w.point.f.x =
            hero_2B33E8.motion.pos.f[0] + FastCos(fast_atan2(hero_2B33E8.facing_x, hero_2B33E8.facing_y)) * 2.0f;
        w.point.f.y =
            hero_2B33E8.motion.pos.f[1] + FastSin(fast_atan2(hero_2B33E8.facing_x, hero_2B33E8.facing_y)) * 2.0f;
        w.point.f.z = hero_2B33E8.motion.pos.f[2] + 1.0f;
        if (data->light == -1) {
            data->light = allocate_colored_effect_slot(&w.point, 6.0f, 0.0f, a, b, c);
        } else {
            Light_2B5C98 *e = &level_point_lights_r2[data->light];
            qcopy(&e->pos, &w.point);
            e->pos.f.w = 6.0f;
            e->x = a;
            e->y = b;
            e->z = c;
        }
        fast_dec_timer_r3(&data->glow);
    } else if (data->light != -1) {
        release_point_light_slot(data->light);
        data->light = -1;
        data->glow = 0;
    }
}

